-- 2. the journal (sync.py): who made a change, its node, how visible it was, the version it edited
alter table sync_changes add column if not exists author_member_id text;
alter table sync_changes add column if not exists author_level integer;
alter table sync_changes add column if not exists node_id text;
alter table sync_changes add column if not exists vis integer;
alter table sync_changes add column if not exists base_ts text;
alter table sync_changes add column if not exists base_origin text;
create or replace function nc_sync_annotate() returns trigger language plpgsql security definer
set search_path from current as $f$
declare r jsonb; p_ts text; p_origin text; p_node text; p_vis integer;
begin
  select s.ts, s.origin, s.node_id, s.vis into p_ts, p_origin, p_node, p_vis from sync_changes s
    where s.tbl = NEW.tbl and s.pk = NEW.pk order by s.seq desc limit 1;
  if NEW.row is not null then r := NEW.row::jsonb; end if;
  NEW.author_member_id := coalesce(NEW.author_member_id, nullif(current_setting('notecad.member', true), ''));
  NEW.author_level := coalesce(NEW.author_level, nullif(current_setting('notecad.level', true), '')::integer);
  if NEW.via is null and NEW.base_ts is null then
    NEW.base_ts := p_ts;
    NEW.base_origin := p_origin;
  end if;
  NEW.node_id := coalesce(NEW.node_id, case NEW.tbl when 'nodes' then NEW.pk when 'node_aliases' then r->>'node_id' when 'edges' then r->>'src_id' when 'notes' then r->>'node_id' when 'tasks' then r->>'node_id' when 'alerts' then r->>'node_id' when 'route_corrections' then r->>'node_id' when 'action_log' then r->>'node_id' when 'member_scopes' then r->>'node_id' end, p_node);
  NEW.vis := coalesce(NEW.vis, case NEW.tbl
    when 'nodes' then (r->>'eff_level')::integer
    when 'captures' then (r->>'eff_level')::integer
    when 'capture_events' then (select c.eff_level from captures c where c.id = r->>'capture_id')
    when 'edges' then least((select n.eff_level from nodes n where n.id = r->>'src_id'), (select n.eff_level from nodes n where n.id = r->>'dst_id'))
    when 'profile_facts' then case r->>'visibility' when 'owner' then 1 when 'manager' then 2 when 'all' then 3 end
    else (select n.eff_level from nodes n where n.id = NEW.node_id) end, p_vis);
  return NEW;
end $f$;
drop trigger if exists nc_sync_annotate on sync_changes;
create trigger nc_sync_annotate before insert on sync_changes for each row execute function nc_sync_annotate();
drop trigger if exists nc_sync_member_scopes on member_scopes;
create trigger nc_sync_member_scopes after insert or update or delete on member_scopes for each row execute function nc_sync_capture('member_id', 'node_id');
drop trigger if exists nc_sync_seats on seats;
create trigger nc_sync_seats after insert or update or delete on seats for each row execute function nc_sync_capture('id');
drop trigger if exists nc_sync_invites on invites;
