drop policy if exists action_log_update on action_log;
drop policy if exists action_log_delete on action_log;
create policy action_log_read on action_log for select to authenticated using (case nc_level(workspace_id) when 1 then true when 2 then member_id = nc_member(workspace_id) or (node_id is not null and nc_sees_rows(node_id) and nc_in_scope(node_id)) when 3 then member_id = nc_member(workspace_id) else false end);
alter table notifications enable row level security;
drop policy if exists notifications_read on notifications;
drop policy if exists notifications_write on notifications;
drop policy if exists notifications_insert on notifications;
drop policy if exists notifications_update on notifications;
drop policy if exists notifications_delete on notifications;
create policy notifications_read on notifications for select to authenticated using (member_id = nc_member(workspace_id) or nc_level(workspace_id) = 1);
alter table route_corrections enable row level security;
drop policy if exists route_corrections_read on route_corrections;
drop policy if exists route_corrections_write on route_corrections;
drop policy if exists route_corrections_insert on route_corrections;
drop policy if exists route_corrections_update on route_corrections;
drop policy if exists route_corrections_delete on route_corrections;
create policy route_corrections_read on route_corrections for select to authenticated using (nc_sees_rows(node_id));
create policy route_corrections_insert on route_corrections for insert to authenticated with check (case nc_write_level(workspace_id) when 1 then true when 2 then nc_in_scope(node_id) else false end and nc_sees_rows(node_id));
create policy route_corrections_delete on route_corrections for delete to authenticated using (case nc_write_level(workspace_id) when 1 then true when 2 then nc_in_scope(node_id) else false end and nc_sees_rows(node_id));
